# Now let's automate this process for all songs in the todo_songs list:
# For each song, search for it, pick the best match, and extract the release month/year.
# We'll build a mapping from song title to release month/year.

release_info = {}

for song in todo_songs:
    query = f"{song['title']} {' '.join(song['artists'])}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the best match: exact title and at least one matching artist
    best = None
    for result in results:
        if result["title"].lower() == song["title"].lower():
            song_artists = set(a.lower() for a in song["artists"])
            result_artists = set(a["name"].lower() for a in result["artists"])
            if song_artists & result_artists:
                best = result
                break
    if best:
        dt = datetime.strptime(best["release_date"], "%Y-%m-%dT%H:%M:%S")
        release_info[song["title"]] = f"{dt.month:02d}/{dt.year}"
    else:
        release_info[song["title"]] = "UNKNOWN"

print(release_info)

